# Generated by Phase: IMPLEMENT | Feature: EVOL-103
"""Accepted change aligned (EVOL-103, [LAW-17]): an accepted change aligns its artefact in the same pull request and
is never reverted.

Every decision log the change touches — `docs/project_log/features/{FEAT}.log.jsonl`, whatever the branch is called
(a fix branch too); the feature id comes from the log's file name — is judged, the tree on disk against the
merge-base with the diff base. Every `action: accepted-change` entry the change ADDS to a log:

  (a) ratified    exactly one of `rdr` (the verbatim choice) or `delegation` ({quote, date}); `id` AC-{FEAT}-{N},
                  `artefacts` and `paths` non-empty lists of repo-relative FILE paths (no absolute path, no `..`,
                  no control byte, never a directory nor a decision log). Neither, both or a malformed entry → red.
  (b) aligned     every artefact it names is in the change — an artefact left untouched is a stale artefact.
  (c) kept        at least one of its `paths` differs from the base — every path back at the base is a revert.
  (d) approved    an artefact APPROVED at the base and not APPROVED on disk, whose latest iteration (LAW-09, the one
                  reader) holds only `accepted_change` changes — a registration-only realignment keeps APPROVED.
And every changed artefact:
  (e) backed      each `accepted_change` of its latest iteration names (`ref`) a ratified accepted-change entry in
                  its feature's decision log on disk — added by this change or an earlier one.

The decision logs themselves are not "the change" for (b)/(c). Nothing to judge → `aligned: n/a`. No config key.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from .common import GateFault, clean as _clean, frontmatter_of, iteration_state, read_frontmatter
from .digests import changed_paths
from .seal import DEFAULT_SEAL_DIR, _git, _norm_path, _reference, vcfg

ACTION = "accepted-change"
KIND = "accepted_change"
LOG = "docs/project_log/features/{fid}.log.jsonl"
LOG_RE = re.compile(r"docs/project_log/features/([^/]+)\.log\.jsonl")


def _lines(text: str | None) -> list[str]:
    return [ln.strip() for ln in (text or "").splitlines() if ln.strip()]


def _at(repo: Path, ref: str, path: str) -> str | None:
    try:
        return _git(repo, "show", f"{ref}:{path}")
    except GateFault:
        return None


def _near(action) -> bool:
    return isinstance(action, str) and action.strip().lower().replace("_", "-") == ACTION


def _read(repo: Path, log: str) -> str:
    p = repo / log
    return p.read_text(encoding="utf-8", errors="replace") if p.is_file() else ""


def added_entries(repo: Path, ref: str, log: str) -> list[dict | str]:
    """The accepted-change lines on disk that the base does not carry: parsed entries (a near-miss action too — judged
    malformed, never skipped), or the raw line when it mentions the action but is not a JSON object."""
    before = set(_lines(_at(repo, ref, log)))
    out: list[dict | str] = []
    for ln in _lines(_read(repo, log)):
        if ln in before:
            continue
        try:
            e = json.loads(ln)
        except json.JSONDecodeError:
            if ACTION in ln or KIND in ln:
                out.append(ln)
            continue
        if isinstance(e, dict) and _near(e.get("action")):
            out.append(e)
    return out


def _str_list(v) -> bool:
    return isinstance(v, list) and bool(v) and all(isinstance(x, str) and x.strip() for x in v)


def _bad_path(repo: Path, p: str) -> str | None:
    if any(not ch.isprintable() for ch in p) or p.startswith("/") or re.match(r"[A-Za-z]:", p) or ".." in p.replace("\\", "/").split("/"):
        return "absolute, `..` or a control byte"
    n = _norm_path(p)
    if n.endswith("/") or (repo / n).is_dir():
        return "a directory — name the files"
    if LOG_RE.fullmatch(n):
        return "a decision log — the log is the record, never the change"
    return None


def ratification(e: dict) -> list[str]:
    rdr, dlg = e.get("rdr"), e.get("delegation")
    has_rdr = isinstance(rdr, str) and bool(rdr.strip())
    has_dlg = isinstance(dlg, dict) and all(isinstance(dlg.get(k), str) and dlg[k].strip() for k in ("quote", "date"))
    if "rdr" in e and "delegation" in e:
        return ["carries both `rdr` and `delegation` — one ratification, never two"]
    if not (has_rdr or has_dlg):
        return ["not ratified — record the user's verbatim choice (`rdr`) or the standing delegation's quote and date (`delegation`)"]
    return []


def malformed(e: dict, fid: str, repo: Path) -> list[str]:
    """Clause (a): the entry's shape and its ratification."""
    problems = []
    if e.get("action") != ACTION:
        problems.append(f"action `{_clean(e.get('action'))}` is not exactly `{ACTION}`")
    if not re.fullmatch(rf"AC-{re.escape(fid)}-\d+", str(e.get("id") or "")):
        problems.append(f"id `{_clean(e.get('id'))}` is not AC-{_clean(fid)}-<N>")
    for k in ("artefacts", "paths"):
        if not _str_list(e.get(k)):
            problems.append(f"`{k}` must list at least one path")
            continue
        for p in e[k]:
            why = _bad_path(repo, p)
            if why:
                problems.append(f"`{k}` item `{_clean(p)}` is not a repo-relative file path ({why})")
    return problems + ratification(e)


def _status(fm: dict) -> str:
    return str(fm.get("status") or "").strip().upper()


def _latest_changes(fm: dict) -> list:
    """The latest iteration's changes (the one reader, LAW-09)."""
    hist = iteration_state(fm)["history"]
    latest = hist[-1] if hist and isinstance(hist[-1], dict) else {}
    ch = latest.get("changes")
    return ch if isinstance(ch, list) else []


def registration_only(fm: dict) -> bool:
    ch = _latest_changes(fm)
    return bool(ch) and all(isinstance(c, dict) and c.get("kind") == KIND for c in ch)


def dropped_approval(repo: Path, ref: str, art: str) -> bool:
    """Clause (d)."""
    disk = repo / art
    before = _at(repo, ref, art)
    if before is None or not disk.is_file():
        return False
    try:
        b, a = frontmatter_of(before), read_frontmatter(disk)
    except GateFault:
        return False
    return _status(b) == "APPROVED" and _status(a) != "APPROVED" and registration_only(a)


def _backed(repo: Path, ref_id: str) -> bool:
    """A ratified accepted-change entry with this id in its feature's decision log on disk (any line)."""
    m = re.fullmatch(r"AC-(.+)-\d+", ref_id)
    if not m or not LOG_RE.fullmatch(LOG.format(fid=m.group(1))):
        return False
    for ln in _lines(_read(repo, LOG.format(fid=m.group(1)))):
        try:
            e = json.loads(ln)
        except json.JSONDecodeError:
            continue
        if isinstance(e, dict) and e.get("action") == ACTION and e.get("id") == ref_id and not ratification(e):
            return True
    return False


def claims(repo: Path, changed: set[str]) -> list[dict]:
    """Clause (e): the changed artefacts whose registration-only claims name no ratified entry (red rows only)."""
    rows = []
    for art in sorted(changed):
        if not art.endswith(".md") or not (repo / art).is_file():
            continue
        try:
            fm = read_frontmatter(repo / art)
        except GateFault:
            continue
        refs = [c.get("ref") for c in _latest_changes(fm) if isinstance(c, dict) and c.get("kind") == KIND]
        if not refs:
            continue
        orphan = [str(r) for r in refs if not (isinstance(r, str) and _backed(repo, r))]
        if orphan:   # a backed claim is a row of its entry's own, never a second one
            rows.append({"id": _clean(art), "ok": False, "problems": [
                f"a registration-only claim with no accepted change behind it: ref {', '.join(_clean(r) for r in orphan)} names no ratified `{ACTION}` entry in the decision log"]})
    return rows


def check(repo: Path, base: str, branch: str | None = None, control_point: str = "push") -> dict:
    """`branch` is accepted for the CLI's signature; the logs the change touches decide, never the branch name."""
    try:
        cfg = vcfg(repo)
    except GateFault:
        cfg = {"dir": DEFAULT_SEAL_DIR}
    ref = _reference(repo, base)
    every = {_norm_path(c) for c in changed_paths(repo, base, cfg)}
    logs = sorted(c for c in every if LOG_RE.fullmatch(c) and (repo / c).is_file())
    changed = {c for c in every if not LOG_RE.fullmatch(c)}
    rows = []
    for log in logs:
        fid = LOG_RE.fullmatch(log).group(1)
        for e in added_entries(repo, ref, log):
            if isinstance(e, str):
                rows.append({"id": "(unreadable)", "ok": False, "problems": [f"a decision-log line in {log} is not JSON — rewrite it as one object: {_clean(e[:80])}"]})
                continue
            problems = malformed(e, fid, repo)
            if not problems:
                arts, paths = [_norm_path(a) for a in e["artefacts"]], [_norm_path(p) for p in e["paths"]]
                stale = [a for a in arts if a not in changed]
                if stale:
                    problems.append(f"stale artefact left in the pull request: {', '.join(stale)} — align it through its owner phase's refine")
                if not any(p in changed for p in paths):
                    problems.append(f"every path ({', '.join(paths)}) is back at the base — a revert of an accepted change; restore it and align the artefact instead")
                dropped = [a for a in arts if dropped_approval(repo, ref, a)]
                if dropped:
                    problems.append(f"{', '.join(dropped)} lost APPROVED on a registration-only realignment — an iteration of only accepted_change changes keeps APPROVED")
            rows.append({"id": _clean(e.get("id") or "(no id)"), "ok": not problems, "problems": problems})
    rows += claims(repo, changed)
    if not rows:
        why = "the change adds no accepted change to its decision log(s)" if logs else "no decision log in the change (docs/project_log/features/*.log.jsonl), no unbacked registration-only claim"
        return {"ok": True, "logs": logs, "entries": [], "reason": f"{why} — nothing to judge"}
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "logs": logs, "entries": rows,
            "reason": f"{len(red)} of {len(rows)} accepted change(s) not aligned" if red else f"{len(rows)} accepted change(s) aligned in this pull request"}


def render(res: dict) -> str:
    if not res.get("entries"):
        return _clean(f"aligned: {'n/a' if res['ok'] else 'RED'} — {res['reason']}")
    lines = [f"aligned: {'ok' if res['ok'] else 'RED'} — {res['reason']} ({', '.join(res['logs']) or 'no decision log changed'})"]
    for r in res["entries"]:
        lines.append(f"  {'✓' if r['ok'] else '✗'} {r['id']}: {'; '.join(r['problems']) or 'ratified, artefact aligned, change kept'}")
    return "\n".join(_clean(ln) for ln in lines)
